**Gates before launch.** I run four gates in order. If any gate fails, I halt and report.

1. **Grader selftest.** `grade.py` must give the oracle output (built from `spe/evals/tasks/answers.json`) a pass on all 50 tickets. It must fail an empty output and a wrong-label output on every ticket. I also check that `judge.md` passes one known-good reply and fails one known-rude reply.
2. **Control regrade.** I regrade the round 3 trial outputs with today's grader. The numbers must match what `spe/prediction-log.md` records for round 3. A mismatch means the grader has a bug. I log that bug in `spe/failures.md`, and it blocks launch.
3. **Dry run.** I run the script with `args.cells` set to three cells (`B/T001`, `C2/T001`, `C2/T002`) and `args.trials = 1`. I confirm that the outputs match the schema, the grader and judge return results, and the peek scan is clean. I then set `args.cost` from the per-trial spend I measured. If 500 trials at that cost would go over $40, I stop and ask you. Cutting trials would change the approved plan.
4. **Prediction check and harness commit.** I confirm that `git diff` is empty for `spe/predictions/r04.yaml`. Then I commit the script as `spe/evals/harness/r04-workflow.js` with the message `SPE r04 evaluate (harness)` and launch it.

I chose these defaults because the plan does not cover them:
- A cell is one config on one ticket. That gives 100 cells and 500 base trials.
- The config, ticket and grader command paths follow the round 3 layout.
- Every agent uses Opus, because the plan names no model for them.

```js
export const meta = {
  name: 'spe-eval-round',
  description: 'SPE eval: configs B and C2 on 50 tickets, 5 trials per cell, code grader on label, Opus tone judge, spend cap.',
  phases: ['Setup', 'Trials', 'Extra trials', 'Analysis', 'Critic'],
};

// ---------- Round constant. Every path and label derives from it. ----------
const ROUND = 4;
const R = 'r' + String(ROUND).padStart(2, '0');
const RUN_DIR = `spe/evals/runs/${R}`;
const A = typeof args === 'object' && args !== null ? args : {};

phase('Setup');

const CONFIGS = A.configs ?? {
  B: {
    prompt: 'spe/evals/configs/B/prompt.md',
    tools: 'spe/evals/configs/B/tools.json',
    note: '12-line prompt, 6 tools',
  },
  C2: {
    prompt: 'spe/evals/configs/C2/prompt.md',
    tools: 'spe/evals/configs/C2/tools.json',
    note: '12-line prompt, 3 tools plus a separate check_status tool',
  },
};
const CONFIG_NAMES = Object.keys(CONFIGS);
const TICKETS = A.tickets ?? Array.from({ length: 50 }, (_, i) => 'T' + String(i + 1).padStart(3, '0'));
const TRIALS = A.trials ?? 5;
const EXTRA_CAP = A.extraTrialsCap ?? 5;
const PLAN_CAP_USD = 40; // approved plan. args may lower it, never raise it.
const CAP_USD = Math.min(Number(A.capUsd ?? PLAN_CAP_USD), PLAN_CAP_USD);
const MAX_GRADER_ERRORS = A.maxGraderErrors ?? 3;
const MODEL_TRIAL = A.trialModel ?? 'opus';
const MODEL_GRADE = A.gradeModel ?? 'opus';
const MODEL_JUDGE = 'opus';
const GRADE_CMD = A.gradeCmd ??
  'python3 spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json --output {file}';
const ticketPath = (t) => `spe/evals/tasks/tickets/${t}.json`;

// Cost estimates come from the dry run. They are estimates, not measured spend.
const COST = A.cost ?? {};
for (const key of ['trial', 'gradePerTrial', 'judgePerTrial', 'analysis']) {
  if (!(Number(COST[key]) > 0)) {
    throw new Error(`args.cost.${key} is required. Set it from the dry run before launch.`);
  }
}
const PER_TRIAL_USD = Number(COST.trial) + Number(COST.gradePerTrial) + Number(COST.judgePerTrial);

// ---------- Budget. JS is single-threaded, so reserve() is atomic. ----------
let spent = 0;
let halted = null;
let graderErrors = 0;
const skips = [];

function reserve(usd, what) {
  if (halted) {
    skips.push({ what, usd, reason: `halted: ${halted}` });
    return false;
  }
  if (spent + usd > CAP_USD) {
    skips.push({ what, usd, reason: 'cap', spentAtSkip: Number(spent.toFixed(2)) });
    log(`SKIP ${what}: $${(spent + usd).toFixed(2)} would cross the $${CAP_USD} cap`);
    return false;
  }
  spent += usd;
  return true;
}

if (!reserve(Number(COST.analysis) * 2, 'reserve for failure analysis and critic')) {
  throw new Error('Cap too small to cover analysis and critic. Halting before any trial.');
}

// ---------- Peek scan. Trials must not read graders, answers, predictions, or other runs. ----------
const FORBIDDEN = [
  /spe\/evals\/graders/, /answers\.json/, /spe\/predictions/, /spe\/plans/,
  /prediction-log/, /failures\.md/, /spe\/spec\//, /spe\/evals\/harness/, /spe\/evals\/runs\//,
];

function peekCheck(out, ownOutPath, allowed) {
  const items = [...(out.files_read ?? []), ...(out.commands_run ?? [])];
  for (const raw of items) {
    const s = String(raw).split(ownOutPath).join('<own-output>');
    const hit = FORBIDDEN.find((re) => re.test(s));
    if (hit) return { void: true, reason: `forbidden access: ${raw}` };
  }
  const offList = (out.files_read ?? []).filter((f) => !allowed.includes(f));
  return { void: false, offList };
}

// ---------- Schemas ----------
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['label', 'reply', 'tools_called', 'files_read', 'commands_run', 'output_path'],
  properties: {
    label: {
      type: 'object',
      required: ['category', 'priority'],
      properties: { category: { type: 'string' }, priority: { type: 'string' } },
    },
    reply: { type: 'string' },
    tools_called: { type: 'array', items: { type: 'string' } },
    files_read: { type: 'array', items: { type: 'string' } },
    commands_run: { type: 'array', items: { type: 'string' } },
    output_path: { type: 'string' },
  },
};

const GRADE_SCHEMA = {
  type: 'object',
  required: ['results'],
  properties: {
    results: {
      type: 'array',
      items: {
        type: 'object',
        required: ['file', 'exit_code', 'category_ok', 'priority_ok'],
        properties: {
          file: { type: 'string' },
          exit_code: { type: 'integer' },
          category_ok: { type: 'boolean' },
          priority_ok: { type: 'boolean' },
          note: { type: 'string' },
        },
      },
    },
  },
};

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['verdicts'],
  properties: {
    verdicts: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'tone_pass', 'reason'],
        properties: {
          id: { type: 'string' },
          tone_pass: { type: 'boolean' },
          score: { type: 'number' },
          reason: { type: 'string' },
        },
      },
    },
  },
};

const ANALYSIS_SCHEMA = {
  type: 'object',
  required: ['failure_types'],
  properties: {
    failure_types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['name', 'kind', 'what', 'how_to_spot', 'seen_in', 'proposed_fix'],
        properties: {
          name: { type: 'string' },
          kind: { type: 'string', enum: ['agent', 'grader', 'judge', 'harness', 'task'] },
          what: { type: 'string' },
          how_to_spot: { type: 'string' },
          seen_in: { type: 'array', items: { type: 'string' } },
          configs: { type: 'array', items: { type: 'string' } },
          proposed_fix: { type: 'string' },
        },
      },
    },
  },
};

const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps', 'halt_recommended', 'reason'],
  properties: {
    complete: { type: 'boolean' },
    gaps: {
      type: 'array',
      items: {
        type: 'object',
        required: ['what', 'severity'],
        properties: {
          what: { type: 'string' },
          cells: { type: 'array', items: { type: 'string' } },
          severity: { type: 'string', enum: ['blocking', 'note'] },
        },
      },
    },
    halt_recommended: { type: 'boolean' },
    reason: { type: 'string' },
  },
};

// ---------- Cells ----------
const cellsAll = [];
for (const config of CONFIG_NAMES) for (const ticket of TICKETS) cellsAll.push({ config, ticket });
const CELLS = Array.isArray(A.cells) && A.cells.length ? A.cells : cellsAll;
const cellKey = (c) => `${c.config}/${c.ticket}`;
log(`${R}: ${CELLS.length} cells x ${TRIALS} trials, cap $${CAP_USD}, est $${PER_TRIAL_USD.toFixed(3)} per trial`);

// ---------- Stage 1: trials ----------
async function runTrials(cell, startIdx, count) {
  const cfg = CONFIGS[cell.config];
  const allowed = [cfg.prompt, cfg.tools, ticketPath(cell.ticket)];
  const thunks = [];
  for (let k = startIdx; k < startIdx + count; k++) {
    thunks.push(async () => {
      const id = `${cellKey(cell)}/t${k}`;
      const outPath = `${RUN_DIR}/${cell.config}/${cell.ticket}-t${k}.json`;
      const rec = { id, config: cell.config, ticket: cell.ticket, k, outPath };
      if (!reserve(PER_TRIAL_USD, `trial ${id}`)) return { ...rec, status: 'skipped' };
      let out;
      try {
        out = await agent(
          [
            `You are one trial in an evaluation. Act as the support triage agent defined by config ${cell.config} (${cfg.note}).`,
            `Read exactly these files and no others: ${allowed.join(', ')}.`,
            'Do not open, list, search, or grep any other path under spe/. That includes graders, answer keys, predictions, plans, logs, harness scripts, and other trial outputs.',
            'Follow the config prompt exactly. Use only the tools that the tools file names, in the way it describes.',
            'Produce a label with category and priority, and a reply to the customer.',
            `Write your final output as JSON to ${outPath}. Return the same JSON.`,
            'In files_read and commands_run, list every file you read and every shell command you ran. Be complete and truthful.',
          ].join('\n'),
          { label: `trial ${id}`, phase: 'Trials', schema: TRIAL_SCHEMA, model: MODEL_TRIAL },
        );
      } catch (e) {
        return { ...rec, status: 'error', error: String(e) };
      }
      if (!out) return { ...rec, status: 'error', error: 'no output' };
      const peek = peekCheck(out, outPath, allowed);
      if (peek.void) {
        log(`VOID ${id}: ${peek.reason}`);
        return { ...rec, status: 'void', voidReason: peek.reason, out };
      }
      return { ...rec, status: 'ran', out, offList: peek.offList };
    });
  }
  return parallel(thunks);
}

// ---------- Stage 2: code grader. It runs first and decides label correctness. ----------
async function gradeBatch(cell, trials) {
  const live = trials.filter((t) => t.status === 'ran');
  if (!live.length) return trials;
  let res;
  try {
    res = await agent(
      [
        'Run the code grader on each trial output file below. Do not edit, fix, or rewrite any file.',
        `Command template: ${GRADE_CMD}`,
        'Exit code 0 means pass, 1 means fail, and 2 or higher means grader error. Report the exit code exactly.',
        'Read category_ok and priority_ok from the grader stdout. If the file is missing, report exit_code 3 and note "missing".',
        'Files:',
        ...live.map((t) => `- ${t.outPath}`),
      ].join('\n'),
      { label: `grade ${cellKey(cell)}`, phase: 'Trials', schema: GRADE_SCHEMA, model: MODEL_GRADE },
    );
  } catch (e) {
    res = { results: [] };
  }
  const byFile = new Map((res?.results ?? []).map((r) => [r.file, r]));
  for (const t of live) {
    const g = byFile.get(t.outPath);
    if (!g || g.exit_code >= 2) {
      t.graderError = g ? `exit ${g.exit_code} ${g.note ?? ''}` : 'no grader result';
      graderErrors += 1;
      if (graderErrors >= MAX_GRADER_ERRORS && !halted) {
        halted = `grader errors reached ${graderErrors}`;
        log(`HALT: ${halted}. No new trials will launch.`);
      }
      continue;
    }
    t.category_ok = g.category_ok;
    t.priority_ok = g.priority_ok;
    t.label_pass = g.category_ok && g.priority_ok;
  }
  return trials;
}

// ---------- Stage 3: Opus judge for reply tone only ----------
async function judgeBatch(cell, trials) {
  const live = trials.filter((t) => t.status === 'ran' && !t.graderError);
  if (!live.length) return trials;
  let res;
  try {
    res = await agent(
      [
        'You judge reply tone only. Read spe/evals/graders/judge.md and apply its rubric. Read no other file.',
        'Do not judge label correctness. Code has already checked it.',
        `Ticket file for context: ${ticketPath(cell.ticket)}`,
        'Replies (JSON):',
        JSON.stringify(live.map((t) => ({ id: t.id, reply: t.out.reply }))),
      ].join('\n'),
      { label: `judge ${cellKey(cell)}`, phase: 'Trials', schema: JUDGE_SCHEMA, model: MODEL_JUDGE },
    );
  } catch (e) {
    res = { verdicts: [] };
  }
  const byId = new Map((res?.verdicts ?? []).map((v) => [v.id, v]));
  for (const t of live) {
    const v = byId.get(t.id);
    if (!v) { t.judgeMissing = true; continue; }
    t.tone_pass = v.tone_pass;
    t.tone_reason = v.reason;
    t.full_pass = t.label_pass === true && v.tone_pass === true;
  }
  return trials;
}

// ---------- Base trials ----------
phase('Trials');
const baseResults = await pipeline(
  CELLS,
  async (cell) => ({ cell, trials: await runTrials(cell, 0, TRIALS) }),
  async (x) => ({ cell: x.cell, trials: await gradeBatch(x.cell, x.trials) }),
  async (x) => ({ cell: x.cell, trials: await judgeBatch(x.cell, x.trials) }),
);
const cellMap = new Map(baseResults.map((x) => [cellKey(x.cell), { cell: x.cell, trials: x.trials }]));

// ---------- Extra trials for split cells ----------
phase('Extra trials');
const scored = (ts) => ts.filter((t) => t.status === 'ran' && !t.graderError && !t.judgeMissing);
const isSplit = (ts) => {
  const s = scored(ts);
  if (s.length < 2) return false;
  const lab = s.filter((t) => t.label_pass).length;
  const tone = s.filter((t) => t.tone_pass).length;
  return (lab > 0 && lab < s.length) || (tone > 0 && tone < s.length);
};
const splitCells = [...cellMap.values()].filter((c) => isSplit(c.trials));
log(`${splitCells.length} split cells get up to ${EXTRA_CAP} extra trials each`);
await parallel(splitCells.map((c) => async () => {
  let extra = await runTrials(c.cell, TRIALS, EXTRA_CAP);
  extra = await gradeBatch(c.cell, extra);
  extra = await judgeBatch(c.cell, extra);
  c.trials.push(...extra);
  c.extra = extra.filter((t) => t.status !== 'skipped').length;
}));

// ---------- Aggregate in code ----------
const allTrials = [...cellMap.values()].flatMap((c) => c.trials);
const rate = (n, d) => (d ? Number((n / d).toFixed(3)) : null);
const perConfig = {};
for (const name of CONFIG_NAMES) {
  const ts = allTrials.filter((t) => t.config === name);
  const s = scored(ts);
  perConfig[name] = {
    trials_planned: CELLS.filter((c) => c.config === name).length * TRIALS,
    scored: s.length,
    skipped: ts.filter((t) => t.status === 'skipped').length,
    voided: ts.filter((t) => t.status === 'void').length,
    errors: ts.filter((t) => t.status === 'error').length,
    grader_errors: ts.filter((t) => t.graderError).length,
    category_acc: rate(s.filter((t) => t.category_ok).length, s.length),
    priority_acc: rate(s.filter((t) => t.priority_ok).length, s.length),
    label_acc: rate(s.filter((t) => t.label_pass).length, s.length),
    tone_pass_rate: rate(s.filter((t) => t.tone_pass).length, s.length),
    full_pass_rate: rate(s.filter((t) => t.full_pass).length, s.length),
    mean_tool_calls: rate(s.reduce((a, t) => a + (t.out.tools_called?.length ?? 0), 0), s.length),
    check_status_rate: rate(s.filter((t) => (t.out.tools_called ?? []).includes('check_status')).length, s.length),
    off_list_reads: s.filter((t) => t.offList?.length).length,
  };
}
log(`Estimated spend $${spent.toFixed(2)} of $${CAP_USD}. Skips: ${skips.length}. Halted: ${halted ?? 'no'}`);

// ---------- Failure analysis ----------
phase('Analysis');
const failing = allTrials
  .filter((t) => t.status === 'void' || t.status === 'error' || t.graderError || t.judgeMissing ||
    (t.status === 'ran' && t.full_pass === false))
  .slice(0, 200)
  .map((t) => ({
    id: t.id, status: t.status, outPath: t.outPath, category_ok: t.category_ok, priority_ok: t.priority_ok,
    tone_pass: t.tone_pass, tone_reason: t.tone_reason, graderError: t.graderError, voidReason: t.voidReason,
    error: t.error,
  }));
let analysis = { failure_types: [] };
if (failing.length) {
  analysis = await agent(
    [
      `Analyze the failing trials of this eval round (${R}). Group them into failure types.`,
      `You may read trial outputs under ${RUN_DIR}/, spe/evals/tasks/, and spe/evals/graders/.`,
      'Do not read spe/predictions/ or spe/plans/. The analysis must stay blind to the predictions.',
      'For each type, give a name, kind, what happens, how to spot it, the trial IDs, the configs, and a proposed fix.',
      'If the grader or judge looks wrong for a trial, report it as kind "grader" or "judge". Do not change any file.',
      'Failing trials (JSON):',
      JSON.stringify(failing),
    ].join('\n'),
    { label: 'failure analysis', phase: 'Analysis', schema: ANALYSIS_SCHEMA, model: 'opus' },
  );
}

// ---------- Completeness critic ----------
phase('Critic');
const coverage = [...cellMap.values()].map((c) => ({
  cell: cellKey(c.cell),
  scored: scored(c.trials).length,
  skipped: c.trials.filter((t) => t.status === 'skipped').length,
  voided: c.trials.filter((t) => t.status === 'void').length,
  extra: c.extra ?? 0,
}));
const critic = await agent(
  [
    `Check this eval round (${R}) for completeness. Do not read any file. Use only the data below.`,
    `Planned: ${CELLS.length} cells x ${TRIALS} trials, configs ${CONFIG_NAMES.join(', ')}, cap $${CAP_USD}.`,
    `Every cell should have ${TRIALS} scored trials, or a logged skip or void for each one that is missing.`,
    'Flag grader errors, missing judge verdicts, voided trials, cap skips, a halt, and any config whose numbers rest on too few trials.',
    'Mark a gap as blocking if it makes a per-config number unreliable.',
    'Data (JSON):',
    JSON.stringify({ perConfig, coverage, skips: skips.slice(0, 100), skipCount: skips.length, halted,
      graderErrors, estimatedSpend: Number(spent.toFixed(2)), failureTypes: analysis.failure_types.map((f) => f.name) }),
  ].join('\n'),
  { label: 'completeness critic', phase: 'Critic', schema: CRITIC_SCHEMA, model: 'opus' },
);

return {
  round: R,
  cap_usd: CAP_USD,
  estimated_spend_usd: Number(spent.toFixed(2)),
  spend_note: 'Estimate from args.cost. Compare with measured usage at close-out.',
  halted,
  skips,
  per_config: perConfig,
  split_cells: splitCells.map((c) => cellKey(c.cell)),
  coverage,
  failure_types: analysis.failure_types,
  critic,
  transcript_scan_note: 'In-script peek scan used self-reported reads and commands. Grep the trial transcripts for forbidden paths at close-out before writing results.',
};
```
